def solve(inputs: dict) -> float:
    def pick(keys, default=None):
        for k in keys:
            if k in inputs:
                return inputs[k]
        return default

    x = pick(('X', 'x', 's', 'start', 'initial', 'seed'))
    a = pick(('a', 'multiplier', 'mul', 'coefficient'))
    c = pick(('c', 'increment', 'add', 'offset'))
    m = pick(('m', 'modulus', 'mod'))
    n = pick(('n', 'times', 'iterations', 'updates', 'repetitions'))

    if None in (x, a, c, m, n):
        nums = inputs.get('values') or inputs.get('numbers')
        if nums is not None and len(nums) >= 5:
            x, n, a, c, m = nums[:5]

    x, a, c, m, n = map(int, (x, a, c, m, n))
    for _ in range(n):
        x = (a * x + c) % m
    return float(x)

