def solve(inputs: dict) -> float:
    def pick(names):
        for name in names:
            if name in inputs:
                return inputs[name]
        return None

    base = pick(('base', 'a', 'number', 'x'))
    exponent = pick(('exponent', 'exp', 'power', 'n'))
    modulus = pick(('modulus', 'mod', 'm', 'divisor'))
    if None in (base, exponent, modulus):
        nums = inputs.get('values') or inputs.get('numbers')
        if nums is not None and len(nums) >= 3:
            base, exponent, modulus = nums[:3]
    return float(pow(int(base), int(exponent), int(modulus)))

