def solve(inputs: dict) -> float:
    residues = None
    moduli = None
    for k in ('residues', 'remainders', 'a', 'values'):
        if k in inputs:
            residues = inputs[k]
            break
    for k in ('moduli', 'mods', 'm'):
        if k in inputs:
            moduli = inputs[k]
            break
    if residues is None or moduli is None:
        pairs = inputs.get('congruences')
        if pairs is not None:
            residues, moduli = zip(*pairs)
    x, product = 0, 1
    for residue, modulus in zip(residues, moduli):
        residue, modulus = int(residue), int(modulus)
        step = ((residue - x) * pow(product, -1, modulus)) % modulus
        x += product * step
        product *= modulus
        x %= product
    return float(x)

